package run.ikaros.sharing; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class PersistentInviteService implements InviteService{private final InviteRepository invites;private final RoomRepository rooms;private final RoomMembershipRepository members;public PersistentInviteService(InviteRepository i,RoomRepository r,RoomMembershipRepository m){invites=i;rooms=r;members=m;}public Mono<InviteView> create(UUID a,UUID roomId,CreateInviteRequest q){return rooms.findById(roomId).filter(r->r.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Room 不存在或无权邀请"))).flatMap(r->invites.findByIssuerIdAndIdempotencyKey(a,q.idempotencyKey()).switchIfEmpty(Mono.defer(()->{Instant n=Instant.now();if(q.expiresAt()!=null&&!q.expiresAt().isAfter(n))return Mono.error(new IllegalArgumentException("Invite 过期时间必须在未来"));return invites.save(new InviteEntity(null,roomId,a,q.inviteeId(),q.role()==null?RoomRole.MEMBER:q.role(),q.idempotencyKey(),InviteStatus.PENDING,q.expiresAt(),n,n,null));}))).map(this::view);}public Flux<InviteView> list(UUID a){return invites.findAllByInviteeIdOrderByCreatedAtDesc(a).map(this::view);}public Mono<InviteView> accept(UUID a,UUID id){return invite(a,id).flatMap(i->{if(i.status()!=InviteStatus.PENDING)return Mono.error(new ConflictException("Invite 当前不可接受"));return members.findByRoomIdAndPrincipalId(i.roomId(),a).flatMap(m->members.save(new RoomMembershipEntity(m.id(),m.roomId(),m.principalId(),i.role(),m.joinedAt(),null,Instant.now(),m.version()))).switchIfEmpty(members.save(new RoomMembershipEntity(null,i.roomId(),a,i.role(),Instant.now(),null,Instant.now(),null))).then(invites.save(new InviteEntity(i.id(),i.roomId(),i.issuerId(),i.inviteeId(),i.role(),i.idempotencyKey(),InviteStatus.ACCEPTED,i.expiresAt(),i.createdAt(),Instant.now(),i.version())));}).map(this::view);}public Mono<InviteView> decline(UUID a,UUID id){return invite(a,id).flatMap(i->update(i,InviteStatus.DECLINED)).map(this::view);}public Mono<InviteView> revoke(UUID a,UUID id){return invites.findById(id).filter(i->i.issuerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Invite 不存在或无权撤销"))).flatMap(i->update(i,InviteStatus.REVOKED)).map(this::view);}private Mono<InviteEntity> invite(UUID a,UUID id){return invites.findById(id).filter(i->i.inviteeId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Invite 不存在")));}private Mono<InviteEntity> update(InviteEntity i,InviteStatus s){return i.status()!=InviteStatus.PENDING?Mono.error(new ConflictException("Invite 当前不可变更")):invites.save(new InviteEntity(i.id(),i.roomId(),i.issuerId(),i.inviteeId(),i.role(),i.idempotencyKey(),s,i.expiresAt(),i.createdAt(),Instant.now(),i.version()));}private InviteView view(InviteEntity i){return new InviteView(i.id(),i.roomId(),i.issuerId(),i.inviteeId(),i.role(),i.idempotencyKey(),i.status(),i.expiresAt(),i.createdAt());}}
